// Generates the osra API reference from ../src with typedoc, as markdown pages Starlight can serve,
// plus the sidebar module astro.config.mjs imports and the symbol map the prose auto-linker reads.
//
// Everything it writes is gitignored and regenerated by the predev/prebuild hooks in package.json,
// because docs/ and src/ are the same repo here: there is no reason to commit output that can go
// stale. (fkn/dev commits its equivalent only because its source lives in a separate private repo
// its Cloudflare build never checks out.)
//
// Run: npm run gen:reference -w docs

import { fileURLToPath } from 'node:url'
import { dirname, resolve, relative } from 'node:path'
import { readdirSync, readFileSync, writeFileSync, statSync, rmSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import { Application, ReflectionKind, TSConfigReader } from 'typedoc'
import GithubSlugger from 'github-slugger'
import { cleanText, identOf } from './clean-text.mjs'
import { GUIDE_LINKS } from '../src/lib/guide-links.mjs'

const HERE = dirname(fileURLToPath(import.meta.url))
const DOCS = resolve(HERE, '..')
const ROOT = resolve(DOCS, '..')
const OUT_DOCS = resolve(DOCS, 'src/content/docs/api')
const OUT_MAP = resolve(DOCS, 'src/lib/api-map.generated.mjs')
const OUT_SIDEBAR = resolve(DOCS, 'src/lib/api-sidebar.generated.mjs')
const ROUTE_BASE = '/api'

// ORDER IS LOAD-BEARING: leaf modules first, the package barrel last. osra publishes a single entry
// point, so the page split comes from which FILE declares a symbol, and typedoc awards a
// declaration to the first entry point that reaches it. Put src/index.ts first and it claims all
// 148 re-exports, collapsing every other page to nothing.
// [source file, page basename, sidebar and frontmatter title]
const ENTRIES = [
  ['src/types.ts', 'types', 'Types'],
  ['src/utils/transport.ts', 'transports', 'Transports'],
  ['src/utils/type-guards.ts', 'type-guards', 'Type guards'],
  ['src/connections/index.ts', 'connections', 'Connections'],
  ['src/revivables/index.ts', 'revivables', 'Revivables'],
  ['src/utils/index.ts', 'utilities', 'Utilities'],
  ['src/index.ts', 'core', 'Core'],
]

// Reading order, which is not resolution order: the barrel leads because expose() is the API.
const SIDEBAR_ORDER = ['core', 'types', 'transports', 'type-guards', 'connections', 'revivables', 'utilities']

// keyed off the absolute sources[0].fullFileName; the relative fileName shifts with typedoc's
// basePath, so do not switch to it
const ABS_TO_PAGE = Object.fromEntries(ENTRIES.map(([src, page]) => [resolve(ROOT, src), page]))
const TITLES = Object.fromEntries(ENTRIES.map(([, page, title]) => [page, title]))
const PAGE_SET = new Set(ENTRIES.map(([, page]) => page))
const routeOf = (page) => `${ROUTE_BASE}/${page}/`

// typedoc's group heading -> the word the A-Z index uses for one symbol
const KIND_LABEL = {
  Functions: 'Function',
  Classes: 'Class',
  Interfaces: 'Interface',
  'Type Aliases': 'Type',
  Variables: 'Variable',
  Namespaces: 'Namespace',
  Enumerations: 'Enum',
}

const log = (...a) => console.log('[gen-reference]', ...a)

// Typedoc pins every "Defined in:" link to the HEAD sha, which is what makes them permalinks that
// never rot. The cost is that they 404 until that commit is on GitHub. A Cloudflare build always
// checks out a pushed commit so its links are valid by construction, but a local build on unpushed
// work emits hundreds of dead links with nothing to say so. Say so.
const headIsPushed = () => {
  try {
    const git = (...args) => execFileSync('git', args, { cwd: ROOT, encoding: 'utf8' }).trim()
    // any remote-tracking branch containing HEAD means the sha is fetchable on the remote
    if (git('branch', '-r', '--contains', 'HEAD')) return true
    return { head: git('rev-parse', '--short', 'HEAD'), ahead: git('rev-list', '--count', '@{u}..HEAD') }
  } catch {
    // no git, no upstream, or a detached checkout with no remote refs: nothing useful to report,
    // and typedoc degrades to plain text when it cannot resolve a repository at all
    return true
  }
}

const app = await Application.bootstrapWithPlugins(
  {
    tsconfig: resolve(ROOT, 'tsconfig.json'),
    entryPoints: ENTRIES.map(([src]) => resolve(ROOT, src)),
    entryPointStrategy: 'resolve',
    plugin: ['typedoc-plugin-markdown'],
    theme: 'markdown',
    // osra builds with typescript 7 while typedoc runs on typescript 5.9; reporting type errors
    // from the older compiler would be noise about a build that is not the one that ships
    skipErrorChecking: true,

    // --- typedoc core ---
    // honours the four symbols src/connections/utils.ts already marks @internal. Nothing else is
    // hidden: the whole point of the page is that it lists every export.
    excludeInternal: true,
    excludePrivate: true,
    // without it, lib.dom and lib.esnext types get pulled in bodily
    excludeExternals: true,
    readme: 'none',
    githubPages: false,
    // one page per entry point
    router: 'module',
    groupOrder: ['Functions', 'Classes', 'Interfaces', 'Type Aliases', 'Variables', '*'],
    // gitRevision / sourceLinkTemplate / disableGit stay unset on purpose. Left alone, typedoc
    // reads the real HEAD sha and emits permalinks that survive a shallow detached Cloudflare
    // checkout, and degrades to plain text when there is no .git at all. Setting
    // disableGit + sourceLinkTemplate emits a WRONG url, because the assumed-repository path
    // resolves against the entry-point dir instead of the git root and loses the src/ segment.

    // --- typedoc-plugin-markdown ---
    // declarations as ```ts fences rather than one long escaped line
    useCodeBlocks: true,
    // without it Remote<T> prints as (...args) => R and loses the `infer P` that makes it readable
    expandParameters: true,
    // without it an object type prints as `type MessageBase = object`
    expandObjects: true,
    // one fence per declaration instead of a cascade of h6 headings, and no prose is lost
    typeDeclarationVisibility: 'compact',
    // escapes bare generics like IdentityWrapper<T> written outside backticks in a doc comment,
    // which would otherwise reach the page as raw html
    sanitizeComments: true,
    hidePageHeader: true,
    hideBreadcrumbs: true,
    // Starlight renders the frontmatter title as the page h1; typedoc's would be a second one
    hidePageTitle: true,
    // the barrel re-exports all 148 symbols, which renders as a wall of links to their real pages.
    // The A-Z index page below does that job properly.
    excludeReferences: true,
    entryFileName: 'index',
    // reformats the type fences; without prettier installed this silently no-ops, so the run is
    // checked for the plugin's skip message below
    formatWithPrettier: true,
    // must be a FILE path, not a directory: prettier.resolveConfig searches from its dirname, so a
    // directory resolves to null and every fence silently falls back to prettier defaults
    prettierConfigFile: resolve(DOCS, '.prettierrc'),
    out: OUT_DOCS,
  },
  [new TSConfigReader()],
)

let sawPrettierSkip = false
const stdoutWrite = process.stdout.write.bind(process.stdout)
process.stdout.write = (chunk, ...rest) => {
  if (String(chunk).includes('Prettier formatting skipped')) sawPrettierSkip = true
  return stdoutWrite(chunk, ...rest)
}

const project = await app.convert()
if (!project) throw new Error('typedoc convert failed')

// Rename entry modules to their page name AFTER resolution (sources are attached) and BEFORE urls
// are built. Skipping this leaves a nested tree (utils/transport.md) whose ../x.md links a flat
// rewrite silently leaves dead, and demotes the barrel to index-1.md because entryFileName already
// claims index.
for (const mod of project.getReflectionsByKind(ReflectionKind.Module)) {
  const full = mod.sources?.[0]?.fullFileName
  const page = full && ABS_TO_PAGE[full]
  if (page) mod.name = page
  else log('WARN: unmapped module', mod.name, '<-', full)
}

rmSync(OUT_DOCS, { recursive: true, force: true })
// the 0.28 output api the markdown plugin hooks, NOT generateDocs
await app.generateOutputs(project)
for (const junk of ['README.md', 'modules.md', '.nojekyll']) rmSync(resolve(OUT_DOCS, junk), { force: true })

const walk = (dir) => {
  const out = []
  for (const name of readdirSync(dir)) {
    const full = resolve(dir, name)
    if (statSync(full).isDirectory()) out.push(...walk(full))
    else if (name.endsWith('.md')) out.push(full)
  }
  return out.sort()
}

const fm = (s) => `"${String(s).replace(/"/g, '\\"')}"`

// "page#Name" -> url, disambiguated with the group when one page declares a name twice (a const and
// a type of the same name, which osra does three times)
const canonical = {}
// bare name -> Set(url), so an ambiguous name can be dropped instead of picking a page at random
const aliasUrls = {}
// every recorded symbol, for the A-Z index
const symbols = []

for (const file of walk(OUT_DOCS)) {
  const page = relative(OUT_DOCS, file).replace(/\.md$/, '')
  if (!PAGE_SET.has(page)) continue // typedoc's own entry page, replaced wholesale below
  const route = routeOf(page)
  let md = readFileSync(file, 'utf8')

  // guard, not a fix: hidePageTitle means there is no h1, but one reaching the page would consume a
  // slug and shift every -N suffix after it
  md = md.replace(/^#\s+.+\n+/m, '')

  // typedoc emits links relative to the file, so resolve against its own directory rather than
  // assuming a flat tree. `](#anchor)` is deliberately not matched: those are already correct.
  md = md.replace(/\]\(([^)\s#]+?)\.md(#[^)\s]*)?\)/g, (m, target, anchor = '') => {
    const targetPage = relative(OUT_DOCS, resolve(dirname(file), `${target}.md`)).replace(/\.md$/, '')
    return PAGE_SET.has(targetPage) ? `](${routeOf(targetPage)}${anchor})` : m
  })

  // point a bare signature at the page that actually explains it
  md = md.replace(/^(###\s+.+)$/gm, (line, heading) => {
    const guide = GUIDE_LINKS[identOf(heading.replace(/^###\s+/, ''))]
    return guide ? `${line}\n\nGuide: [${guide.label}](${guide.route})` : line
  })

  // Anchors come from re-slugging the FINAL body, never from the symbol name. Every heading at
  // every depth advances the slugger, because a parameter or property heading routinely displaces
  // the symbol that follows it: Uuid is #uuid-1, isJsonOnlyTransport is #isjsononlytransport-1
  // because its case-only twin came first.
  const slugger = new GithubSlugger()
  let group = null
  let inFence = false
  for (const line of md.split('\n')) {
    if (/^\s*```/.test(line)) { inFence = !inFence; continue }
    if (inFence) continue
    const m = line.match(/^(#{2,6})\s+(.+?)\s*$/)
    if (!m) continue
    const anchor = slugger.slug(cleanText(m[2]))
    if (m[1].length === 2) { group = cleanText(m[2]); continue }
    if (m[1].length !== 3) continue // symbols are h3; deeper headings are members and options
    const name = identOf(m[2])
    const url = `${route}#${anchor}`
    const key = `${page}#${name}`
    canonical[key in canonical ? `${key}:${group}` : key] = url
    ;(aliasUrls[name] ??= new Set()).add(url)
    symbols.push({ name, url, page, kind: KIND_LABEL[group] ?? group })
  }

  writeFileSync(file, `---\ntitle: ${fm(TITLES[page])}\ntableOfContents:\n  maxHeadingLevel: 3\n---\n\n${md}`)
}

// A bare name is only safe to link when it resolves to exactly one place. Where a page declares the
// same name as both a value and a type, prefer the type: it is what a reader writing `Foo` in prose
// means, and both anchors are on the same page anyway.
const aliases = {}
const dropped = []
for (const [name, urls] of Object.entries(aliasUrls)) {
  if (urls.size === 1) { aliases[name] = [...urls][0]; continue }
  const typeUrl = symbols.find((s) => s.name === name && s.kind === 'Type')?.url
  if (typeUrl) aliases[name] = typeUrl
  else dropped.push(`${name} -> ${urls.size} targets`)
}

const banner =
  '// AUTO-GENERATED by scripts/gen-reference.mjs, DO NOT EDIT.\n' +
  '// Run `npm run gen:reference` to regenerate.\n'

writeFileSync(
  OUT_MAP,
  banner +
    '\n// Fully-qualified "page#Name" key -> reference url. Suffixed with the group where one page\n' +
    '// declares a name twice.\n' +
    `export const API_MAP = ${JSON.stringify(canonical, null, 2)}\n\n` +
    '// Bare name -> reference url, only where the name resolves to exactly one symbol. This is what\n' +
    '// the prose auto-linker reads.\n' +
    `export const API_ALIASES = ${JSON.stringify(aliases, null, 2)}\n\n` +
    '// Page name -> route.\n' +
    `export const API_PAGES = ${JSON.stringify(
      Object.fromEntries(SIDEBAR_ORDER.map((p) => [p, routeOf(p)])),
      null,
      2,
    )}\n`,
)

// Replace typedoc's entry page with an A-Z index. Letters are h2 so Starlight's right rail becomes
// the jump list.
const byLetter = {}
for (const s of [...symbols].sort((a, b) => a.name.localeCompare(b.name, 'en', { sensitivity: 'base' }))) {
  const letter = /^[A-Za-z]/.test(s.name) ? s.name[0].toUpperCase() : '#'
  ;(byLetter[letter] ??= []).push(s)
}
const indexBody = Object.entries(byLetter)
  .map(
    ([letter, list]) =>
      `## ${letter}\n\n| Symbol | Kind | Page |\n| --- | --- | --- |\n` +
      list
        .map((s) => `| [\`${s.name}\`](${s.url}) | ${s.kind} | [${TITLES[s.page]}](${routeOf(s.page)}) |`)
        .join('\n'),
  )
  .join('\n\n')

writeFileSync(
  resolve(OUT_DOCS, 'index.md'),
  `---\ntitle: "All symbols"\ndescription: "Every export of the osra package, generated from the source."\ntableOfContents:\n  maxHeadingLevel: 2\n---\n\n` +
    `Every value and type the \`osra\` package exports, ${symbols.length} in all, generated from the source.\n\n` +
    `${indexBody}\n`,
)

writeFileSync(
  OUT_SIDEBAR,
  banner +
    `\nexport const apiSidebar = ${JSON.stringify(
      [
        { label: 'All symbols', slug: 'api' },
        ...SIDEBAR_ORDER.map((page) => ({ label: TITLES[page], slug: `api/${page}` })),
      ],
      null,
      2,
    )}\n`,
)

// Print every file with its byte count. A run that reports only totals is a claim about this
// script, not about the output: an empty walk would otherwise look like a clean result.
let totalBytes = 0
for (const file of walk(OUT_DOCS)) {
  const bytes = Buffer.byteLength(readFileSync(file, 'utf8'))
  totalBytes += bytes
  log(`  wrote ${relative(DOCS, file).padEnd(38)} ${String(bytes).padStart(7)} bytes`)
}
for (const file of [OUT_MAP, OUT_SIDEBAR]) {
  log(`  wrote ${relative(DOCS, file).padEnd(38)} ${String(Buffer.byteLength(readFileSync(file, 'utf8'))).padStart(7)} bytes`)
}
log(`${symbols.length} symbols, ${Object.keys(aliases).length} link aliases, ${totalBytes} bytes of markdown`)
if (dropped.length) log('ambiguous names left unlinked:', dropped.join(', '))

const pushed = headIsPushed()
if (pushed !== true) {
  const links = walk(OUT_DOCS).reduce(
    (n, f) => n + (readFileSync(f, 'utf8').match(/github\.com\/[^)]*\/blob\//g)?.length ?? 0),
    0,
  )
  log(`WARNING: HEAD (${pushed.head}) is ${pushed.ahead} commit(s) ahead of its upstream, so all`)
  log(`         ${links} "Defined in:" source links will 404 on GitHub until you push.`)
  log('         Nothing to fix in the output: they resolve the moment the commit lands.')
}
if (sawPrettierSkip) throw new Error('prettier is not installed, type fences would ship unformatted')
log('done.')
